(() => {
'use strict';
const $=id=>document.getElementById(id),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let data={trips:[],role:''},active='',tab='overview',busy=false,dialogSave,signature=null,challenge='';
const current=()=>data.trips.find(t=>t.id===active),owner=()=>data.role==='organizer',parent=()=>data.role==='parent';
const status=v=>({missing:'Permission needed',received:'Awaiting review',verified:'Verified',changes:'Needs correction','not-permitted':'Permission not granted',draft:'Not submitted',submitted:'Awaiting district review',approved:'District process complete',correction:'District requested corrections',complete:'Complete'})[v]||v;
const districtText=t=>t.district==='draft'&&!t.k12?(owner()?'District form not linked':'District approval pending'):status(t.district);
const chip=(v,tone='neutral')=>`<span class="chip ${tone}">${esc(v)}</span>`;
const btn=(text,action,extra='',primary=false)=>`<button type="button" data-action="${action}" ${extra} class="${primary?'primary':''}">${esc(text)}</button>`;
const stamp=v=>v?new Date(v).toLocaleString('en-US',{timeZone:'America/Los_Angeles',dateStyle:'medium',timeStyle:'short'})+' Pacific':'';
const date=v=>new Date(v+'T12:00:00').toLocaleDateString('en-US',{month:'short',day:'numeric',year:'numeric'});
const field=(name,label,value='',type='text',extra='')=>`<label>${esc(label)}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
const area=(name,label,value='',limit=1500)=>`<label class="wide">${esc(label)}<textarea name="${name}" maxlength="${limit}" rows="3">${esc(value)}</textarea></label>`;
const foods={tbd:'To be determined',asb:'Food provided by ASB',district:'Food provided by district',venue:'Food provided by venue',bring:'Bring your own food',purchase:'Purchase your own food',none:'No meal needed',other:'Other arrangements'};
const foodFields=t=>`<label>Food arrangements<select name="foodChoice">${Object.entries(foods).map(([v,l])=>`<option value="${v}" ${t?.foodChoice===v?'selected':''}>${l}</option>`).join('')}</select></label>${area('food','Food details',t?.foodDetails??t?.food??'',500)}`;
const download=(t,p)=>'/api/field-trips?operation=download&id='+encodeURIComponent(t.id)+'&studentId='+encodeURIComponent(p.id);
function note(text){$('feedback').textContent=text;}
async function api(operation,values={},read=false){const query=new URLSearchParams({operation,...values}),response=await fetch('/api/field-trips'+(read?'?'+query:''),{method:read?'GET':'POST',credentials:'same-origin',cache:'no-store',headers:read?{}:{'Content-Type':'application/json'},...(!read?{body:JSON.stringify({operation,...values})}:{})});const result=await response.json();if(!response.ok)throw Object.assign(Error(result.error||'The action could not be confirmed.'),{status:response.status});return result;}
async function load(){try{const result=await api('bootstrap',{},true);data=result;const fromHash=new URLSearchParams(location.hash.slice(1)).get('trip');if(!active)active=fromHash||result.trips[0]?.id||'';if(!result.trips.some(t=>t.id===active))active=result.trips[0]?.id||'';$('connection-status').classList.remove('has-error');$('connection-status').textContent='Connected · changes are saved to the private trip workspace';$('end-parent').hidden=!parent();render();maybeStudentWelcome();}catch(error){$('connection-status').classList.add('has-error');$('connection-status').textContent=error.message;$('workspace').hidden=true;$('new-trip').hidden=true;if(error.status===401)$('trips').innerHTML='<p class="empty">Sign in to see your field trips. Parents can use their emailed invitation.</p>';throw error;}}
async function mutate(operation,values={}){const t=current();const result=await api(operation,{id:t?.id,revision:t?.revision,...values});let message=result.districtWarning||result.calendarWarning||'Saved.';if(result.delivery){const accepted=result.delivery.filter(d=>d.state==='accepted').length,other=result.delivery.length-accepted;message=accepted+' email(s) accepted by the mail provider.'+(other?' '+other+' delivery result(s) need review. Refresh before retrying.':'');}await load();note(message);return result;}
function studentInviteSnapshot(t,ids){return JSON.stringify({title:t.title,destination:t.destination,address:t.address,purpose:t.purpose,bring:t.bring,food:t.food,foodChoice:t.foodChoice,deadline:t.deadline,days:t.days.map(({date,depart,returnTime,transport})=>({date,depart,returnTime,transport})),people:t.participants.filter(p=>ids.includes(p.id)).map(({id,name,email})=>({id,name,email})).sort((a,b)=>a.id.localeCompare(b.id))});}
async function run(work){if(busy)return;busy=true;document.querySelectorAll('button[type=submit],button[data-action]').forEach(b=>b.disabled=true);try{await work();}catch(error){note(error.message);if($('action-dialog').open)$('action-error').textContent=error.message;try{await load();}catch{} }finally{busy=false;render();$('action-submit').disabled=false;}}
function dialog(title,html,onSave,label='Save'){dialogSave=onSave;$('action-title').textContent=title;$('action-fields').innerHTML=html;$('action-error').textContent='';$('action-cancel').textContent='Cancel';$('action-submit').hidden=false;$('action-submit').textContent=label;$('action-submit').disabled=false;$('action-dialog').showModal();syncRosterGroups();}
const welcomed=new Set();
function welcomeKey(t){return 'nest-triphub-welcome-v1:'+t.id+':'+t.participants[0].id;}
function maybeStudentWelcome(){const t=current();if(data.role!=='student'||!t?.participants[0]||t.participants[0].parent||$('action-dialog').open)return;const key=welcomeKey(t);let seen=welcomed.has(key);try{seen=seen||localStorage.getItem(key)==='1';}catch{}if(!seen)studentWelcome(2);}
function studentWelcome(step=0){const t=current(),p=t?.participants[0];if(data.role!=='student'||!p)return;step=Number(step);if(![0,1,2].includes(step))return;const key=welcomeKey(t);welcomed.add(key);try{localStorage.setItem(key,'1');}catch{}tab=step===0?'overview':step===1?'attendance':'family';render();const nav=`<p class="muted">${step===2?'Your next step':'Quick tour · '+(step+1)+' of 3'} · ${esc(t.title)}</p>`;
 const html=nav+(step===0?`<h3>Start with Trip details</h3><p>This is your trip landing page. Check the destination, dates, transportation, food plan, what to bring, and the permission deadline.</p><p>The trip list lets you switch between events you have been invited to.</p><div class="actions">${btn('Next: event-day tab','welcome-step','data-step="1"')}</div>`:step===1?`<h3>Check in & sign out</h3><p>On the event day, use this tab to check in when Mr. P opens it. Request sign-out here and wait for Mr. P to confirm your departure.</p><p>Permission paperwork does not check you in or sign you out.</p><div class="actions">${btn('Back: trip details','welcome-step','data-step="0"')}${btn('Next: parent permission','welcome-step','data-step="2"')}</div>`:p.parent?`<h3>My paperwork</h3><p>Your parent contact is already saved. This tab shows the progress of the invitation, signature, and Mr. P’s review.</p><p>Your parent signs through their own private emailed link. You can return here to check your status or message Mr. P.</p><div class="actions">${btn('Start the tour','welcome-step','data-step="0"')}${btn('Open My paperwork','welcome-finish')}</div>`:`<h3>Add your parent or guardian email</h3><p>Welcome! Your first step is in <strong>My paperwork</strong>. Enter your parent or guardian’s contact below so they can receive a private invitation to sign your permission form digitally.</p><p>Mr. P reviews the contact before sending the signing invitation. Your parent must review and sign the form themselves.</p><div class="form-grid">${field('name','Parent / guardian name','','text','required maxlength="80"')}${field('email','Parent / guardian email','','email','required')}${field('emailConfirm','Repeat parent email','','email','required')}</div><p>Check the address with your parent. Come back to My paperwork to see your permission status. Need help? Ask Mr. P.</p><div class="actions">${btn('Show me the tabs first','welcome-step','data-step="0"')}</div>`);
 const save=async f=>{if(current()?.id!==t.id||data.role!=='student')throw Error('The trip changed. Close this window and reopen the welcome guide for your current trip.');if(f.get('email')!==f.get('emailConfirm'))throw Error('The parent email entries must match.');await mutate('parent-contact',{name:f.get('name'),email:f.get('email')});tab='family';render();note('Parent contact saved. Mr. P will review it before sending the private signing invitation.');};
 if(!$('action-dialog').open)dialog('Welcome to TripHub',html,save,'Save parent contact');else{dialogSave=save;$('action-title').textContent='Welcome to TripHub';$('action-fields').innerHTML=html;$('action-error').textContent='';$('action-submit').textContent='Save parent contact';}
 $('action-submit').hidden=step!==2||!!p.parent;$('action-submit').disabled=false;$('action-cancel').textContent='Not now';
}
function render(){const t=current();$('student-welcome').hidden=data.role!=='student'||!t;$('new-trip').hidden=!owner();$('trip-count').textContent=data.trips.length;$('trips').innerHTML=data.trips.map(t=>`<button class="trip-item" data-trip="${esc(t.id)}" aria-current="${active===t.id}"><small>${esc(date(t.days[0].date))} · ${esc(t.days[0].transport)}</small><strong>${esc(t.title)}</strong>${chip(districtText(t),t.district==='approved'?'good':'neutral')}</button>`).join('')||'<p class="empty">No trips are assigned to you.</p>';$('workspace').hidden=!t;if(!t)return;$('trip-title').textContent=t.title;$('trip-subtitle').textContent=t.destination+' · '+date(t.days[0].date);$('trip-stage').textContent=t.days.some(d=>d.open)?'EVENT IN PROGRESS':'YOUR NEXT EXPERIENCE';$('trip-month').textContent=new Date(t.days[0].date+'T12:00:00').toLocaleDateString('en-US',{month:'short'}).toUpperCase();$('trip-day').textContent=Number(t.days[0].date.slice(-2));$('trip-facts').innerHTML=[['LEAVE SCHOOL',t.days[0].depart],['RETURN TO SCHOOL',t.days[0].returnTime],['TRANSPORTATION',t.days[0].transport]].map(([l,v])=>`<div class="fact"><small>${l}</small><strong>${esc(v)}</strong></div>`).join('');
 const tabs=owner()?[['overview','Overview'],['students','Students'],['district','District request'],['family','Parent permissions'],['attendance','Event day'],['notifications','Notifications'],['calendar','Calendar'],['transport','Transport & keys']]:parent()?[['overview','Trip details'],['family','Permission & signature']]:[['overview','Trip details'],['family','My paperwork'],['attendance','Check in & sign out']];if(!tabs.some(([v])=>v===tab))tab='overview';$('tabs').innerHTML=tabs.map(([v,l])=>`<button data-tab="${v}" aria-current="${v===tab?'page':'false'}">${l}</button>`).join('');$('panel').innerHTML=({overview,students,district,family,attendance,notifications,calendar,transport}[tab])(t);}
function overview(t){const p=t.participants[0];return `<div class="stat-grid"><div class="stat"><strong>${owner()?t.participants.length:status(p.status)}</strong><span>${owner()?'Students invited':'Your permission status'}</span></div><div class="stat"><strong>${owner()?t.participants.filter(p=>p.status==='verified').length:districtText(t)}</strong><span>${owner()?'Paperwork verified':'District process'}</span></div></div><div class="card"><h3>The details</h3><dl class="district-grid">${[['Destination',t.destination+' · '+t.address],['Learning purpose',t.purpose],['What to bring',t.bring],['Food',window.NestTripIcons.food(t.foodChoice,t.food).emoji+' '+t.food],['Permission deadline',date(t.deadline)]].map(([l,v])=>`<div><dt>${l}</dt><dd>${esc(v)}</dd></div>`).join('')}</dl><h3 style="margin-top:24px">Schedule</h3>${t.days.map(d=>`<p>${esc(date(d.date))} · ${esc(d.depart)}–${esc(d.returnTime)} · ${window.NestTripIcons.transportation(d.transport).map(p=>esc(p.emoji+' '+p.label)).join(' / ')}</p>`).join('')}${owner()?`<div class="actions">${btn('Edit trip details','edit')}${btn('View notification delivery history','delivery-history')}${btn('Refresh district permission template','refresh-template')}${t.participants[0]?(t.templateReady?`<a href="/api/field-trips?operation=preview-pdf&id=${esc(t.id)}&studentId=${esc(t.participants[0].id)}" target="_blank" rel="noopener noreferrer">Preview generated form & itinerary ↗</a>`:btn('Preview generated form & itinerary ↗','prepare-preview')):''}</div><h3 style="margin-top:24px">Download event PDFs</h3><div class="actions"><a href="/api/field-trips?operation=itinerary-pdf&id=${esc(t.id)}" download>Download itinerary PDF</a><a href="/api/field-trips?operation=roster-pdf&id=${esc(t.id)}" download>Download student roster PDF</a><a href="/api/field-trips?operation=district-packet&id=${esc(t.id)}" download>Download itinerary & student roster PDF</a></div><p class="muted">Changing trip details requires a refreshed district permission template and approval review before new signatures.</p>`:''}</div>`;}
function students(t){return `<div class="section-heading"><div><h2>Students on this trip</h2><p>Changes apply to this trip and its calendar invitations.</p></div><div class="actions">${btn('Add / manage students','roster','',true)}${btn('Automatic invitations','roster-groups')}${btn('Sync new group members','sync-roster','',true)}</div></div><div class="card"><div class="table-wrap"><table><thead><tr><th>Student</th><th>Permission</th><th>Review</th></tr></thead><tbody>${t.participants.map(p=>`<tr><td>${esc(p.name)}<small>${esc(p.email)}${p.legacyStatus?' · Imported: '+esc(p.legacyStatus):''}</small></td><td>${chip(status(p.status),p.status==='verified'?'good':'warn')}</td><td><div class="actions">${p.status==='received'?btn('Verify','verify',`data-person="${p.id}"`):btn('Record paper received','paper-received',`data-person="${p.id}"`)}${btn('Needs correction','correction',`data-person="${p.id}"`)}</div></td></tr>`).join('')}</tbody></table></div></div>`;}
function k12Detail(t,id){const f=(data.inbox||[]).find(f=>f.requestId===id);if(!f)return '<p>Select a discovered district form to review its details.</p>';const linked=(data.trips||[]).find(trip=>trip.k12?.requestId===id),blocked=f.conflict||linked&&linked.id!==t.id;return `<article class="district-message"><h4>${esc(f.details?.title||'District form '+id)}</h4><p>${esc(f.details?.destination||'Destination unavailable')} · ${esc(f.details?.departDate||'Trip dates missing')}${f.details?.returnDate?' – '+esc(f.details.returnDate):''}</p><p>Form ID: <strong>${esc(id)}</strong> · ${esc(f.details?.step||'')}</p><p>${chip(status(f.messages?.find(m=>['complete','correction','submitted','saved','not-submitted'].includes(m.status))?.status||'review'))}</p><p>${esc(f.messages?.find(m=>m.summary)?.summary||'Review the district notification.')}</p><p>TripHub association: ${esc(linked?.title||'Not linked')}</p>${blocked?'<p class="error">'+(f.conflict?'Conflicting notification identifiers need review.':'This form is already associated with another trip.')+'</p>':`<div class="actions"><a href="/api/field-trips?operation=open-form&id=${esc(t.id)}&requestId=${esc(id)}" target="_blank" rel="noopener noreferrer">Open selected K12 form ↗</a>${btn('Review & confirm association','link-k12',`data-request="${esc(id)}"`)}</div>`}</article>`;}
function k12Picker(t){return `<section><h3>Choose the district form for this trip</h3><p>Choose a discovered form, review its details, then confirm. Selecting an option does not save a link. Forms already linked to another TripHub trip are excluded.</p><label>Discovered K12 forms<select id="k12-form-picker"><option value="">Choose a district form…</option>${(data.inbox||[]).filter(f=>!(data.trips||[]).some(other=>other.id!==t.id&&other.k12?.requestId===f.requestId)).map(f=>`<option value="${esc(f.requestId)}" ${t.k12?.requestId===f.requestId?'selected':''}>${esc(f.details?.title||'Unidentified activity')} · ${esc(f.details?.departDate||'Date missing')} · ID ${esc(f.requestId)}${f.conflict?' · Needs review':''}</option>`).join('')}</select></label><div id="k12-selection-details">${k12Detail(t,t.k12?.requestId)}</div><h4>Association log</h4>${(t.history||[]).filter(h=>/^District form .* linked to this trip revision\./.test(h.message)).map(h=>`<p>${esc(h.message)} <small>${esc(stamp(h.at))}</small></p>`).join('')||'<p>No form association confirmed yet.</p>'}</section>`;}
async function downloadDistrictPacket(id){try{const response=await fetch('/api/field-trips?operation=district-packet&id='+encodeURIComponent(id),{method:'GET',credentials:'same-origin',cache:'no-store'});if(!response.ok){const error=await response.json();throw Error(error.error||'The attachment packet could not be prepared.');}const url=URL.createObjectURL(await response.blob()),link=document.createElement('a');link.href=url;link.download='NEST-TripHub-'+String(current()?.title||'Trip').replace(/[^a-zA-Z0-9 -]/g,'').slice(0,100)+'-roster-and-itinerary.pdf';document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);return true;}catch(error){note('Trip saved. Attachments could not be downloaded automatically. Use Download roster & itinerary packet in District request. '+error.message);return false;}}
const previousK12=new Map();
const normalizedEventName=value=>String(value||'').toLowerCase().replace(/20\d{2}/g,'').replace(/[^a-z0-9]+/g,' ').trim();
const eventMatch=(title,query)=>!normalizedEventName(query)||normalizedEventName(title).includes(normalizedEventName(query));
function templateOptions(query='',source='trip'){const list=source==='trip'?(data.tripTemplates||[]):(data.inbox||[]).filter(f=>!f.conflict&&f.details?.title).map(f=>({id:f.requestId,title:f.details.title,date:f.details.departDate||''}));return '<option value="">Choose a previous event…</option>'+list.filter(t=>eventMatch(t.title,query)).map(t=>`<option value="${esc(t.id)}">${esc(t.title)}${t.date?' · '+esc(t.date):''}</option>`).join('');}
function priorTripPicker(){return `<section class="wide"><h3>Start from a previous event (optional)</h3><p>Choose an event to populate its trip name, destination, address, purpose, what to bring, and food plan. Dates and students stay as you entered them.</p><label>Match event names<input id="prior-trip-filter" type="search" placeholder="For example: Move in" data-auto="1"></label><label>Previous events<select id="prior-trip-select">${templateOptions()}</select></label><p id="prior-trip-note" role="status"></p></section>`;}
function priorK12Picker(t){const query=/move[ -]*in/i.test(t.title)?'Move in':'';return `<h4>Reuse previous K12 answers (optional)</h4><p>Choose a previous request to populate copy-ready values. Review costs, staffing, qualifications, funding and housing for this trip. Dates, event identity, student count, signatures, approvals, and the current TripHub itinerary data are not replaced.</p><label>Match event names<input type="search" id="prior-k12-filter" value="${esc(query)}" placeholder="For example: Move in"></label><label>Previous district requests<select id="prior-k12-select">${templateOptions(query,'k12')}</select></label><p id="prior-k12-note" role="status">${previousK12.has(t.id)?'Previous-request values are applied below. Verify them before pasting.':''}</p>`;}
function handoffRows(t){const rows=window.NestTripK12Handoff.fields(t),prior=previousK12.get(t.id);if(!prior)return rows;return rows.map(row=>Object.hasOwn(prior.values,row.label)?{...row,value:prior.values[row.label],note:'From '+prior.title+' — verify this answer for the new trip.'}:row);}
function renderHandoffRows(t){return handoffRows(t).map((r,i)=>`<li><label for="k12-copy-${i}">${esc(r.label)}</label>${r.value?`<textarea id="k12-copy-${i}" readonly rows="2">${esc(r.value)}</textarea>${btn('Copy','k12-copy',`data-index="${i}"`)}`:'<p>Review / enter directly in K12.</p>'}${r.note?`<p class="muted">${esc(r.note)}</p>`:''}</li>`).join('');}
function districtDownloads(t){return `<a href="/api/field-trips?operation=itinerary-pdf&id=${esc(t.id)}" download>Download itinerary PDF</a><a href="/api/field-trips?operation=roster-pdf&id=${esc(t.id)}" download>Download student roster PDF</a><a href="/api/field-trips?operation=district-packet&id=${esc(t.id)}" download>Download roster & itinerary packet</a>`;}
function k12Handoff(t){const linked=!!t.k12?.requestId,open=linked?'/api/field-trips?operation=open-form&id='+encodeURIComponent(t.id):window.NestTripK12Handoff?.formUrl,reference=`${priorK12Picker(t)}<details id="k12-copy-fields"><summary>Copy-ready fields in district form order</summary><ol class="k12-copy-list">${renderHandoffRows(t)}</ol></details>`;if(linked)return `<section class="card district-quick-actions" aria-label="Connected district form actions"><div class="section-heading"><h3>Connected district form · ${esc(t.k12.requestId)}</h3>${chip(districtText(t),t.district==='approved'?'good':'warn')}</div><div class="actions"><a href="${esc(open)}" target="_blank" rel="noopener noreferrer">Open linked K12 form ↗</a>${districtDownloads(t)}${btn('Change connected form','change-k12')}</div></section><details class="card" id="k12-association"><summary>Change connected form · ID ${esc(t.k12.requestId)}</summary>${k12Picker(t)}</details><details class="card" id="k12-form-reference"><summary>District form reference & copy-ready fields</summary><p>Use these values when updating the connected district form. Review any corrections and submit changes in K12.</p>${reference}</details>`;return `<div class="card"><h3>Complete the district form</h3><p>Open K12 beside TripHub, then copy each value into its matching box. K12 does not allow its form inside the NEST website. Review all selections and submit there yourself.</p><div class="actions"><a href="${esc(open)}" target="_blank" rel="noopener noreferrer">Start district day-trip request ↗</a>${districtDownloads(t)}</div><p class="muted">The packet contains both documents for attachment. Separate copies are available if requested. Fields requiring confirmation have no suggested value.</p>${reference}</div>`;}

function district(t){return `${k12Handoff(t)}<div class="section-heading"><div><h2>District request</h2><p>Read submission and approval updates from Informed K12.</p></div>${chip(districtText(t),t.district==='approved'?'good':'warn')}</div><div class="card"><h3>District email tracking</h3><p>Check submission, correction, and approval emails after using the district form.</p><div class="actions">${btn('Check K12 email','sync-mail')}${btn('Inspect a form link','inspect-k12')}</div><p class="muted">Mailbox last checked: ${esc(stamp(data.lastMailboxSync)||'Not yet checked')}. Scheduled checks run every 15 minutes.</p></div>${t.k12?.requestId?'':`<div class="card">${k12Picker(t)}</div>`}<div class="card"><div class="section-heading"><h3>District notification timeline</h3>${chip(t.k12?.requestId?'Form '+t.k12.requestId:'Not linked')}</div>${t.k12?.needsReview?'<div class="note">Trip details changed. Update the district form and confirm its association with this revision.</div>':''}${t.k12?.requestId?`<a href="/api/field-trips?operation=open-form&id=${esc(t.id)}" target="_blank" rel="noopener noreferrer">Open your district form ↗</a>`:''}<div class="district-timeline">${(t.k12?.messages||[]).map(m=>`<article class="district-message"><div>${chip(status(m.status),m.status==='complete'?'good':m.status==='correction'?'bad':'neutral')}<time>${esc(stamp(m.at))}</time></div><h4>${esc(m.subject)}</h4><p>${esc(m.summary)}</p>${m.rosterRequested?`<div class="actions"><a href="/api/field-trips?operation=roster-pdf&id=${esc(t.id)}&messageId=${esc(m.id)}" download data-action="download-roster" data-request="${esc(t.k12.requestId)}">Download roster PDF & open K12 ↗</a><small>Current invited students · dated snapshot for attaching in K12</small></div>`:''}</article>`).join('')||'<p>No district notifications linked to this trip yet.</p>'}</div></div><div class="card"><h3>Record a district decision</h3><form id="district-manual"><label>Status<select name="value">${['draft','submitted','correction','approved'].map(v=>`<option value="${v}" ${v===t.district?'selected':''}>${status(v)}</option>`).join('')}</select></label>${field('reference','Confirmation reference',t.districtReference||'','text','maxlength="200"')}<button type="submit">Save decision</button></form></div>`;}
function familyThread(t,p){return `<div class="card"><h3>Shared family updates${owner()?' · '+esc(p.name):''}</h3><p class="muted">Shared with the student, their parent, and Mr. P. Keep health and emergency-contact details in the private permission document.</p><div class="family-thread">${(p.messages||[]).map(m=>`<div><strong>${esc(m.actor)}</strong><p>${esc(m.text)}</p><small>${esc(stamp(m.at))}</small></div>`).join('')||'<p>No shared messages yet.</p>'}</div><form data-message="${p.id}">${area('message','Shared update','',500)}<button type="submit">Post update</button></form></div>`;}
function parentRequestHistory(p){const request=p.parentRequest;if(!request)return '';const recipient=request.recipient||{},labels={submitted:'Parent contact submitted',invited:'Guardian contact verified; invitation prepared','email-reserved':'Invitation awaiting email confirmation','email-accepted':'Invitation accepted by email provider','email-rejected':'Invitation rejected by email provider','email-unknown':'Invitation email status unconfirmed',opened:'Parent opened the signing link','email-verified':'Parent verified email access',signed:'Parent signed; awaiting organizer review',completed:'Permission verified by organizer',correction:'Corrections requested; new signature needed',declined:'Parent declined permission'},waiting=request.stage==='contact-review';return `<section class="card parent-request-history"><h3>Parent signature request history</h3><p>Parent / guardian: <strong>${esc(recipient.name)}</strong> · ${recipient.email?`<a href="mailto:${esc(encodeURIComponent(recipient.email))}">${esc(recipient.email)}</a>`:esc(recipient.maskedEmail||'')}</p><p>${waiting?'Waiting for Mr. P to verify the guardian contact. The parent invitation has not been sent yet.':'Email-provider acceptance does not confirm inbox receipt. Opening, email verification, and signing are recorded separately.'}</p><ol class="trip-delivery-list">${(request.events||[]).map(e=>`<li><strong>${esc(labels[e.kind]||status(e.kind))}</strong><p>${esc(e.name||recipient.name)}${e.email?' · '+esc(e.email):''}</p><small>${e.at?esc(stamp(e.at)):'Timestamp unavailable for this earlier record'}</small></li>`).join('')}</ol></section>`;}
function family(t){if(owner())return `<div class="card"><h2>Parent permissions</h2><p>Check the guardian contact before sending a private invitation.</p>${t.participants.map(p=>`<div class="district-message"><strong>${esc(p.name)}</strong><p>${p.parent?esc(p.parent.name+' · '+p.parent.email)+' · '+esc(status(p.parent.stage)):'Parent email needed'}</p><div class="actions">${p.parent?btn('Verify contact & send invitation','invite-parent',`data-person="${p.id}"`):''}${p.parent?.hasPdf?`<a href="${download(t,p)}">Download signed PDF</a>`:''}</div></div>`).join('')}</div>`+t.participants.map(p=>parentRequestHistory(p)+familyThread(t,p)).join('');
 const p=t.participants[0];const templateUrl='/api/field-trips?operation=blank-permission&id='+encodeURIComponent(t.id);if(!parent())return `<div class="card"><h2>My paperwork</h2>${chip(status(p.status),p.status==='verified'?'good':'warn')}<p><a href="${templateUrl}" target="_blank" rel="noopener noreferrer">Open the district permission form ↗</a></p><p>Provide your parent or guardian’s email so they can review and sign your trip-specific permission form. A paper copy can also be returned to Mr. P.</p><p>${p.parent?'Parent progress: '+esc(status(p.parent.stage)):''}</p><form id="parent-contact"><div class="form-grid">${field('name','Parent / guardian name',p.parent?.name||'','text','required maxlength="80"')}${field('email','Parent / guardian email','','email','required')}${field('emailConfirm','Repeat parent email','','email','required')}</div><button type="submit">Submit parent contact</button></form></div>`+parentRequestHistory(p)+familyThread(t,p);
 const signed=p.parent?.stage==='signed',declined=p.parent?.stage==='declined';return `<div class="card"><h2>Parent / guardian permission for ${esc(p.name)}</h2><p>Review the original district permission form and the trip details before signing.</p><iframe class="permission-document" title="District permission form" src="${templateUrl}"></iframe><p><a href="${templateUrl}" target="_blank" rel="noopener noreferrer">Open full-size district form ↗</a></p>${chip(status(p.parent?.stage))}${declined?'<p>You declined permission. Contact Mr. P if you need to change that decision.</p>':signed?`<p>Your signed form was received and is awaiting organizer review.</p><a href="${download(t,p)}">Download signed form & itinerary</a>`:`<form id="parent-signature"><div class="form-grid">${field('name','Parent / guardian full name',p.parent?.name||'','text','required maxlength="80"')}${field('relationship','Relationship to student','','text','required maxlength="40"')}${field('homePhone','Home phone','','tel','maxlength="30"')}${field('workPhone','Work phone','','tel','maxlength="30"')}${field('extension','Extension','','text','maxlength="15"')}${field('cellPhone','Cell phone','','tel','required maxlength="30"')}${field('address','Home address','','text','required maxlength="160"')}${area('medical','Medical conditions, medical information, or allergies','',110)}${field('emergencyName1','Emergency contact 1 name','','text','required maxlength="80"')}${field('emergencyPhone1','Emergency contact 1 phone','','tel','required maxlength="30"')}${field('emergencyName2','Emergency contact 2 name','','text','maxlength="80"')}${field('emergencyPhone2','Emergency contact 2 phone','','tel','maxlength="30"')}</div><button type="button" data-action="draw-signature" class="signature-line">${signature?'Signature captured · tap to review':'Tap to sign with your finger, stylus, or mouse'}</button><label class="contact"><input type="checkbox" name="consent" required><span>I am this child’s parent or guardian. I have reviewed this trip’s information and authorize my child to participate. I agree to sign electronically.</span></label><div class="actions"><button type="submit" class="primary">Sign & submit permission</button>${btn('Decline permission','decline')}</div><p class="muted">Your private medical and emergency-contact entries appear in the signed PDF for you and authorized staff. They are not shown in the student’s account.</p></form>`}</div>`+parentRequestHistory(p)+familyThread(t,p);}
function calendar(t){return `<div class="card"><h2>Calendar & invitations</h2><p>Edit this trip’s title, location, dates and times here, or add/remove students. These changes apply to the associated trip and permission-deadline events. Remove a trip day to cancel its events; removing every student cancels all associated events. Direct edits in Google Calendar can be replaced on the next TripHub sync.</p>${chip(t.calendarPending?'Changes pending':'No pending roster changes',t.calendarPending?'warn':'good')}<div class="actions">${btn('Edit trip details & dates','edit')}${btn('Add / remove invited students','roster')}${btn('Refresh & review calendar changes','calendar-plan','',true)}</div><div class="table-wrap"><table><thead><tr><th>Calendar</th><th>Date / event</th><th>Invited students</th></tr></thead><tbody>${(t.calendarEvents||[]).map(e=>`<tr><td>${esc(e.calendarName)}</td><td>${esc(e.date)}<small>${esc(e.title)}</small>${e.eventId?`<a href="https://calendar.google.com/calendar/event?eid=${encodeURIComponent(btoa(e.eventId.replace(/@google\.com$/,'' )+' '+e.calendarId))}" target="_blank" rel="noopener noreferrer">Open / edit in Google Calendar ↗</a>`:''}</td><td>${esc(e.guests.join(', '))}</td></tr>`).join('')}</tbody></table></div></div>`;}
function transport(t){const required=t.days.some(d=>/van/i.test(d.transport)),v=t.van||{};return `<div class="card"><h2>Transport & keys</h2>${t.days.map(d=>`<p>${esc(date(d.date))} · ${esc(d.transport)}</p>`).join('')}${required?`${chip(v.confirmed?'Office confirmed':'Office confirmation needed',v.confirmed?'good':'warn')}<p>District completion does not confirm driver authorization, reserve a van, or arrange key pickup.</p><div class="actions">${btn('Preview van-key confirmation email','van-notify','',true)}</div><form id="van-confirm"><h3>Record the office’s response</h3>${[['driver','My name is currently on the authorized-driver list for every trip date.'],['reserved','A suitable van is reserved.'],['keys','The office confirmed key pickup arrangements.']].map(([n,l])=>`<label class="contact"><input type="checkbox" name="${n}" required ${v.confirmed?'checked':''}><span>${l}</span></label>`).join('')}<div class="form-grid">${field('by','Confirmed by',v.by||'','text','required maxlength="100"')}${field('reference','Confirmation reference',v.reference||'','text','required maxlength="200"')}${field('pickup','Key pickup date & time',v.pickup||'','datetime-local','required')}${field('where','Pickup person / location',v.where||'','text','required maxlength="200"')}</div><div class="actions"><button type="submit">Record confirmation</button>${btn('Authorization or van changed','van-revoke')}</div></form>`:'<p>No van selected. Edit trip details to change transportation.</p>'}</div>`;}
function deliveryHistory(t){const rows=t.deliveries||[],rejected=rows.filter(d=>d.state==='rejected').length,unconfirmed=rows.filter(d=>['unknown','reserved'].includes(d.state)).length;return `<section class="card" id="trip-delivery-history" tabindex="-1"><h2>Notification delivery history</h2><p>${rows.length} saved send${rows.length===1?'':'s'}${rejected?' · '+rejected+' rejected':''}${unconfirmed?' · '+unconfirmed+' awaiting confirmation':''}. Acceptance by the mail provider does not guarantee inbox delivery.</p>${rows.length?`<details ${rejected||unconfirmed?'open':''}><summary>Review recipients and delivery results</summary><ul class="trip-delivery-list">${rows.map(d=>`<li><div>${(d.recipients||[]).map(r=>`<a href="mailto:${esc(encodeURIComponent(r.email))}">${esc(r.name||r.email)}</a>`).join(', ')} ${chip(({accepted:'Accepted by mail provider',rejected:'Rejected',unknown:'Unconfirmed',reserved:'Awaiting confirmation'})[d.state]||d.state,d.state==='rejected'?'bad':d.state==='accepted'?'good':'warn')}</div><p>${esc(({onboarding:'Student invitation',invitation:'Permission invitation',reminder:'Paperwork reminder',details:'Trip information',change:'Trip update',changed:'Updated permission',absence:'Attendance notice',van:'Van confirmation'})[d.stage]||status(d.stage))} · ${esc(status(d.audience))} · ${esc(stamp(d.completedAt||d.at))}</p>${d.errorMessage?`<p>${esc(d.errorMessage)}</p>`:d.errorCode?`<p>Provider code ${esc(d.errorCode)}</p>`:d.state==='rejected'?'<p>The original provider rejection reason was not retained for this older send.</p>':''}</li>`).join('')}</ul></details>`:'<p>No notification sends have been recorded for this event.</p>'}</section>`;}
function notifications(t){return `${deliveryHistory(t)}<div class="card"><h2>Invite students to TripHub</h2><p>Send each selected student an individual invitation with this trip’s link and instructions for adding a parent email. Choose only newly added students when you need to follow up.</p><form id="student-invitations">${t.participants.map(p=>`<label class="contact"><input type="checkbox" name="students" value="${esc(p.id)}" checked><span><a href="mailto:${esc(encodeURIComponent(p.email))}">${esc(p.name)}</a></span></label>`).join('')}<button type="submit">Review student invitations</button></form></div><div class="card"><h2>Notifications</h2><p>Preview recipients before sending. Student reminders are sent individually.</p><form id="notification"><label>Purpose<select name="kind"><option value="details">Trip information</option><option value="missing">Missing-permission reminder</option><option value="absence">Event-day absence notice</option><option value="change">Trip update</option></select></label>${area('note','Additional note','',1500)}<h3>Invited students (${t.participants.length})</h3><ul>${t.participants.map(p=>`<li>${esc(p.name)}${p.period?` · ${esc(p.period)}`:''}</li>`).join('')}</ul><h3>Staff recipients</h3>${(data.contacts||[]).map(c=>`<label class="contact"><input type="checkbox" name="contacts" value="${esc(c.id)}" ${c.office?'checked':''}><span>${esc(c.name)}<small>${esc(c.position)} · ${esc(c.email)}</small></span></label>`).join('')}<label class="contact"><input type="checkbox" name="calendar"><span>Also reconcile trip and deadline calendar invitations</span></label><button type="submit">Review before sending</button></form></div>`;}
function attendance(t){return `<div class="card"><h2>Event day</h2><p>Roll call, check-in, and supervised sign-out stay separate from permission status.</p>${t.days.map((d,i)=>`<section class="district-message"><h3>${esc(date(d.date))}</h3>${chip(d.closed?'Closed':d.open?'Check-in open':'Check-in closed')}<div class="actions">${owner()?btn('Open check-in','open-day',`data-day="${i}" ${d.open||d.closed?'disabled':''}`)+btn('Close day','close-day',`data-day="${i}" ${!d.open?'disabled':''}`):''}</div><div class="table-wrap"><table><thead><tr><th>${owner()?'Student':'My status'}</th>${owner()?'<th>Roll call</th>':''}<th>Movement</th><th>Action</th></tr></thead><tbody>${t.participants.map(p=>`<tr><td>${esc(p.name)}<small>${esc(status(p.status))}</small></td>${owner()?`<td><select data-roll="${p.id}" data-day="${i}" ${d.closed?'disabled':''}><option value="">Not marked</option>${['present','excused','absent'].map(v=>`<option value="${v}" ${p.attendance[i]===v?'selected':''}>${v}</option>`).join('')}</select></td>`:''}<td>${esc(p.movement[i]==='in'?'Checked in':p.movement[i]==='out'?'Signed out':'Not checked in')}</td><td>${owner()?(p.requests[i]?btn('Confirm departure','approve-out',`data-person="${p.id}" data-day="${i}"`):''):p.movement[i]==='in'?btn(p.requests[i]?'Awaiting departure confirmation':'Request sign-out','request-out',`data-day="${i}" ${p.requests[i]?'disabled':''}`):btn('Check in','check-in',`data-day="${i}" ${!d.open||d.closed||p.status!=='verified'||p.movement[i]==='out'?'disabled':''}`)}</td></tr>`).join('')}</tbody></table></div></section>`).join('')}</div>${owner()?'<div class="card"><h3>Activity</h3>'+t.history.map(h=>'<p>'+esc(h.message)+'<small> · '+esc(stamp(h.at))+'</small></p>').join('')+'</div>':''}`;}
function dayInputs(d={},i=0){return `<div class="form-grid day-input" data-day-index="${i}">${field('date-'+i,'Trip date',d.date||'','date','required')}${field('depart-'+i,'Leave school',d.depart||'','time','required')}${field('return-'+i,'Return to school',d.returnTime||'','time','required')}<label>Transportation<select name="transport-${i}">${['School bus','District van','Commercial transportation','Private vehicle','Parent drop-off / pick-up'].map(v=>`<option ${(v===d.transport||({'School bus':/bus/i,'District van':/van/i,'Commercial transportation':/commercial/i,'Private vehicle':/private/i,'Parent drop-off / pick-up':/parent/i}[v]).test(d.transport||''))?'selected':''}>${v}</option>`).join('')}</select></label></div>`;}
function selectedPeriods(people){return [...new Set(people.flatMap(p=>[...String(p.period||(p.periods||[]).join(', ')).matchAll(/\b(?:Period\s*)?([1-57])\b|\bCTSO\b/gi)].map(m=>m[1]?'Period '+m[1]:'CTSO')))];}
function routingSummary(people,mode='auto',events=[]){if(!people.length)return '<p>Select students below to see their destination calendars.</p>';const routing=data.calendarRouting||{},periods=selectedPeriods(people);let routes=[];if(mode==='auto'||mode==='periods'){for(const period of periods){const route=routing.byPeriod?.[period];if(!route)return '<p class="error">Calendar mapping needs review for '+esc(period)+'.</p>';if(!routes.some(r=>r.key===route.key))routes.push(route);}}else if(events?.length){routes=[...new Map(events.map(e=>[e.calendarId,{key:e.calendarId,name:e.calendarName}])).values()];}else if(mode==='ctso-leadership'&&routing.byPeriod?.CTSO)routes=[routing.byPeriod.CTSO];if(!routes.length)routes=[routing.fallback||{name:'NEST™ Event Calendar'}];return '<p>Selected periods: '+esc(periods.join(', ')||'No class period listed')+'</p>'+periods.map(period=>'<p>'+esc(period)+' → '+esc(routing.byPeriod?.[period]?.prep||'Prep not configured')+'</p>').join('')+'<ul>'+routes.map(r=>'<li>'+esc(r.name)+(r.reason?' — '+esc(r.reason):'')+'</li>').join('')+'</ul><p>Trip and permission-deadline events use these calendars.</p>';}
function updateRoutingPreview(){const boxes=[$('calendar-routing-preview'),$('roster-calendar-preview')].filter(Boolean);if(!boxes.length)return;const hasPicker=!!document.querySelector('#action-fields input[name=people]'),people=hasPicker?chosenRosterPeople():current()?.participants||[],mode=document.querySelector('#action-fields [name=calendarAudience]')?.value||current()?.calendarAudience||'auto',html=routingSummary(people,mode,hasPicker?[]:current()?.calendarEvents);for(const box of boxes)box.innerHTML=html;}
function locationFields(t){const current=(data.locations||[]).find(l=>l.name.trim().toLowerCase()===t?.destination?.trim().toLowerCase()),custom=!!t?.destination&&!current;return `<label>Destination<select id="destination-select" required><option value="">Choose a saved location…</option>${(data.locations||[]).map(l=>`<option value="${esc(l.id)}" ${current?.id===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}<option value="__new__" ${custom?'selected':''}>＋ Create a new location</option></select></label><input type="hidden" name="destination" value="${esc(t?.destination||'')}"><label id="new-location-fields" ${!custom?'hidden':''}>New location name<input id="new-location-name" name="newLocationName" value="${esc(custom?t.destination:'')}" maxlength="140" ${custom?'required':''}><small>Saved with this trip for use on future events.</small></label>${field('address','Destination address',t?.address||'','text','required maxlength="250"')}`;}
function syncLocationFromTemplate(source){const select=$('destination-select');if(!select)return;const loc=(data.locations||[]).find(l=>l.name.trim().toLowerCase()===String(source.destination||'').trim().toLowerCase());select.value=loc?loc.id:'__new__';$('new-location-fields').hidden=!!loc;$('new-location-name').required=!loc;$('new-location-name').value=loc?'':source.destination||'';}
function tripFields(t){return `<div class="form-grid">${!t?priorTripPicker():''}${field('title','Trip name',t?.title||'','text','required maxlength="140"')}${locationFields(t)}${area('purpose','Learning purpose',t?.purpose||'')}${area('bring','What to bring',t?.bring||'',500)}${foodFields(t)}<input type="hidden" name="calendarAudience" value="${esc(t?.calendarAudience||'auto')}"><section class="wide"><h3>Calendar assignment</h3><p>Assigned automatically using the database: selected students’ period → prep → that prep’s calendar. Periods sharing a prep use one calendar.</p><div id="calendar-routing-preview" aria-live="polite">${routingSummary(t?.participants||[],t?.calendarAudience||'auto',t?.calendarEvents)}</div></section></div><h3>Trip days</h3><div id="edit-days">${(t?.days||[{}]).map(dayInputs).join('')}</div><button type="button" data-action="add-edit-day">Add another trip day</button><button type="button" data-action="remove-edit-day">Remove last trip day</button>`;}
function tripValues(f){const v=Object.fromEntries(f);if($('destination-select')?.value==='__new__')v.destination=v.newLocationName||v.destination;const days=[...$('edit-days').querySelectorAll('.day-input')].map((el,i)=>({date:v['date-'+i],depart:v['depart-'+i],returnTime:v['return-'+i],transport:v['transport-'+i]}));return Object.fromEntries(['title','destination','address','purpose','bring','food','foodChoice','calendarAudience'].map(k=>[k,v[k]||'']).concat([['days',days]]));}
function rosterFields(selected=[],savedGroups=[]){const groups=data.studentGroups||{},saved=new Set(savedGroups),set=new Set(selected),section=(title,items)=>`<fieldset><legend>${title}</legend>${items.map(g=>`<label class="contact"><input type="checkbox" name="studentGroups" data-student-group="${esc(g.id)}" ${saved.has(g.id)?'data-explicit-group="1"':''} value="${esc(g.id)}" ${saved.has(g.id)||g.studentIds.length&&g.studentIds.every(id=>set.has(id))?'checked':''}><span>${esc(g.label)}<small>${g.studentIds.length} students</small></span></label>`).join('')||'<p>No groups available.</p>'}</fieldset>`;return `<p>Check one or more groups, individual students, or both. Each student is invited once. Saved Robotics groups automatically include and invite newly active eligible members before the trip begins.</p><div class="form-grid">${section('Students by division',groups.divisions||[])}${section('Leadership teams by period',groups.leadership||[])}</div>${roboticsRosterPicker(set,saved)}${(groups.warnings||[]).map(w=>`<p class="error">${esc(w)}</p>`).join('')}<button type="button" data-action="roster-clear-all">Clear all selections</button><p id="roster-selected-groups"></p><p id="roster-selected-count" role="status">${selected.length} students selected</p><details><summary>Choose individual students</summary><label>Filter students (optional)<input id="roster-search" type="search" placeholder="Filter the checkbox list"></label><div class="actions"><button type="button" data-action="select-visible">Select visible students</button><button type="button" data-action="clear-visible">Clear visible students</button></div><div class="picker-results">${(data.roster||[]).map(p=>`<label class="roster-option" data-roster-search="${esc((p.name+' '+p.email+' '+p.period).toLowerCase())}"><input type="checkbox" name="people" data-individually-selected="${set.has(p.id)?'1':'0'}" value="${p.id}" ${set.has(p.id)?'checked':''}><span><strong>${esc(p.name)}</strong><small>${esc(p.period)} · ${esc(p.email)}</small></span></label>`).join('')}</div></details><div id="roster-calendar-preview" aria-live="polite"></div>`;}
function roboticsRosterPicker(selected,saved=new Set()){const groups=data.studentGroups?.robotics||[],teams=[...new Set(groups.map(g=>g.team).filter(Boolean))];return `<details class="robotics-roster-picker"><summary>By NEST™ Robotics team</summary><p>Choose team leads, assistants, both, or every member of a team. Switching the team filter keeps existing selections.</p><label>Team<select id="robotics-team-filter"><option value="">All Robotics teams</option>${teams.map(t=>`<option>${esc(t)}</option>`).join('')}</select></label>${groups.map(g=>`<label class="contact" data-robotics-team="${esc(g.team)}" data-robotics-kind="${esc(g.kind)}" ${g.team&&g.kind!=='members'?'hidden':''}><input type="checkbox" name="studentGroups" data-student-group="${esc(g.id)}" ${saved.has(g.id)?'data-explicit-group="1"':''} value="${esc(g.id)}" ${saved.has(g.id)?'checked':''}><span>${esc(g.label)}<small>${g.studentIds.length} students</small></span></label>`).join('')||'<p>Robotics groups are unavailable. Refresh to check the team spreadsheet.</p>'}</details>`;}
function rosterGroupList(){return [...(data.studentGroups?.divisions||[]),...(data.studentGroups?.leadership||[]),...(data.studentGroups?.robotics||[])];}
function syncRosterGroups(){const ids=new Set([...document.querySelectorAll('#action-fields input[name=people]:checked')].map(e=>e.value));for(const box of document.querySelectorAll('[data-student-group]')){const g=rosterGroupList().find(g=>g.id===box.value);if(!g)continue;const count=g.studentIds.filter(id=>ids.has(id)).length;if(count===0)box.dataset.explicitGroup='0';box.checked=box.dataset.explicitGroup==='1'&&count===g.studentIds.length&&count>0;box.indeterminate=count>0&&!box.checked;}if($('roster-selected-count'))$('roster-selected-count').textContent=ids.size+' students selected';if($('roster-selected-groups'))$('roster-selected-groups').textContent='Selected groups: '+(rosterGroupList().filter(g=>chosenGroupIds().includes(g.id)).map(g=>g.label).join('; ')||'Individual selections');updateRoutingPreview();}
function chosenGroupIds(){const selected=new Set([...document.querySelectorAll('#action-fields input[name=people]:checked')].map(e=>e.value));return [...document.querySelectorAll('[data-student-group][data-explicit-group="1"]')].map(e=>e.value).filter(id=>rosterGroupList().find(g=>g.id===id)?.studentIds.some(student=>selected.has(student)));}
function chosenRosterPeople(){const ids=[...document.querySelectorAll('#action-fields input[name=people]:checked')].map(e=>e.value),groupIds=chosenGroupIds();return (data.roster||[]).filter(p=>ids.includes(p.id)).map(p=>{const periods=[...new Set(rosterGroupList().filter(g=>groupIds.includes(g.id)&&g.studentIds.includes(p.id)).map(g=>g.period))];const prior=!document.querySelector('#action-fields [name=calendarAudience]')?current()?.participants.find(old=>old.id===p.id):null;return periods.length?{...p,period:periods.join(', ')}:prior?{...p,period:prior.period}:p;});}
function planHtml(plan){return '<div class="table-wrap"><table><thead><tr><th>Calendar / date</th><th>Action</th><th>Guests</th></tr></thead><tbody>'+plan.map(p=>`<tr><td>${esc(p.calendarName)}<small>${esc(p.date+' · '+p.title)}</small></td><td>${esc(p.action)}</td><td>Add: ${esc(p.add.join(', ')||'none')}<br>Remove: ${esc(p.remove.join(', ')||'none')}</td></tr>`).join('')+'</tbody></table></div>';}
$('action-cancel').onclick=()=>$('action-dialog').close();$('action-form').onsubmit=async e=>{e.preventDefault();if(busy)return;const form=new FormData(e.currentTarget);$('action-submit').disabled=true;try{await dialogSave(form);$('action-dialog').close();}catch(error){$('action-error').textContent=error.message;}finally{$('action-submit').disabled=false;}};
$('student-welcome').onclick=()=>studentWelcome(0);$('refresh').onclick=()=>run(load);$('end-parent').onclick=()=>run(async()=>{await api('parent-logout',{id:current()?.id});data={trips:[],role:''};$('end-parent').hidden=true;render();$('connection-status').textContent='Parent session ended.';});
$('new-trip').onclick=()=>{const creationKey=crypto.randomUUID();dialog('Plan a field trip',tripFields()+`<h3>Students</h3>${rosterFields()}<label class="contact"><input type="checkbox" name="sendStudentInvitations" checked><span>Send student invitations when this trip is created<small>Each selected student receives their own TripHub link and parent-email instructions.</small></span></label><label class="contact"><input type="checkbox" name="districtHandoff" checked><span>Open K12 and download the roster & itinerary after creating this trip</span></label>`,async f=>{const handoff=f.has('districtHandoff');let popup=null;if(handoff){try{popup=window.open('about:blank','_blank','popup,width=1100,height=900');if(popup){popup.opener=null;popup.document.title='Preparing TripHub event';popup.document.body.textContent='TripHub is creating the event. The district form will open here after it is saved.';}}catch{popup=null;}}let result;try{result=await api('create',{trip:{...tripValues(f),participantIds:f.getAll('people'),groupIds:chosenGroupIds(),creationKey,sendStudentInvitations:f.has('sendStudentInvitations')}});}catch(error){try{popup?.close();}catch{}throw error;}active=result.id;tab=handoff?'district':'notifications';await load();let packetReady=false;if(handoff){$('k12-copy-fields')?.setAttribute('open','');try{if(popup)popup.location.replace(window.NestTripK12Handoff.formUrl);}catch{}packetReady=await downloadDistrictPacket(result.id);}const delivery=result.delivery||[],accepted=delivery.filter(d=>d.state==='accepted').length,other=delivery.length-accepted;note(result.alreadyCreated?'Trip already created. Check delivery history before sending again.':f.has('sendStudentInvitations')?'Trip created. '+accepted+' student invitation(s) accepted by the mail provider.'+(other?' '+other+' delivery result(s) need review.':''):'Trip created. Student invitations were not sent.');if(handoff)note($('feedback').textContent+(packetReady?' Roster and itinerary download started.':' Use Download roster & itinerary packet if the automatic download did not complete.')+' District request has the K12 link and copy-ready fields.');},'Create trip');};
document.addEventListener('nest-auth-change',()=>run(load));
document.addEventListener('input',e=>{if(e.target.id==='new-location-name')document.querySelector('#action-fields [name=destination]').value=e.target.value;if(e.target.id==='prior-trip-filter'){e.target.dataset.auto='0';$('prior-trip-select').innerHTML=templateOptions(e.target.value);}if(e.target.id==='prior-k12-filter')$('prior-k12-select').innerHTML=templateOptions(e.target.value,'k12');if(e.target.name==='title'&&$('prior-trip-filter')?.dataset.auto==='1'){const q=/move[ -]*in/i.test(e.target.value)?'Move in':e.target.value;$('prior-trip-filter').value=q;$('prior-trip-select').innerHTML=templateOptions(q);}if(e.target.id==='roster-search')for(const row of document.querySelectorAll('[data-roster-search]'))row.hidden=!row.dataset.rosterSearch.includes(e.target.value.toLowerCase());});
document.addEventListener('change',async e=>{if(e.target.id==='robotics-team-filter'){for(const row of document.querySelectorAll('[data-robotics-team]'))row.hidden=e.target.value?row.dataset.roboticsTeam!==e.target.value:!!row.dataset.roboticsTeam&&row.dataset.roboticsKind!=='members';return;}if(e.target.id==='destination-select'){const loc=(data.locations||[]).find(l=>l.id===e.target.value),custom=e.target.value==='__new__';$('new-location-fields').hidden=!custom;$('new-location-name').required=custom;document.querySelector('#action-fields [name=destination]').value=loc?.name||'';if(loc)document.querySelector('#action-fields [name=address]').value=loc.address;else if(custom)document.querySelector('#action-fields [name=address]').value='';return;}if(e.target.id==='prior-trip-select'){const source=(data.tripTemplates||[]).find(t=>t.id===e.target.value);if(!source)return;for(const key of ['title','destination','address','purpose','bring','food','foodChoice']){const input=document.querySelector('#action-fields [name="'+key+'"]');if(input)input.value=source[key]||'';}syncLocationFromTemplate(source);$('prior-trip-note').textContent='Populated the trip name and details from '+source.title+'. Review the details, choose new dates, and select the students for this event.';return;}if(e.target.id==='prior-k12-select'){const id=e.target.value,t=current();if(!id){previousK12.delete(t.id);document.querySelector('.k12-copy-list').innerHTML=renderHandoffRows(t);$('prior-k12-note').textContent='Using current TripHub data.';return;}const tripId=t.id;e.target.disabled=true;try{const result=await api('previous-k12-answers',{requestId:id},true);if(current()?.id!==tripId)return;const values={};for(const [number,value]of Object.entries(result.answers||{})){const label=window.NestTripK12Handoff.reusableNumbers[number];if(label)values[label]=String(value);}if(!Object.keys(values).length){previousK12.delete(tripId);$('prior-k12-note').textContent='No reusable answers were readable from that request. Review it directly in K12.';document.querySelector('.k12-copy-list').innerHTML=renderHandoffRows(t);return;}previousK12.set(tripId,{title:result.title,values});$('prior-k12-note').textContent='Applied answers from '+result.title+'. Review each value before pasting.';document.querySelector('.k12-copy-list').innerHTML=renderHandoffRows(t);$('k12-copy-fields').open=true;}catch(error){if($('prior-k12-note'))$('prior-k12-note').textContent=error.message;}finally{e.target.disabled=false;}return;}if(e.target.dataset.studentGroup){e.target.dataset.explicitGroup=e.target.checked?'1':'0';const group=rosterGroupList().find(g=>g.id===e.target.value);if(group){const keep=new Set([...document.querySelectorAll('#action-fields input[name=people][data-individually-selected="1"]')].map(e=>e.value).concat(rosterGroupList().filter(g=>g.id!==group.id&&document.querySelector('[data-student-group=\"'+g.id+'\"]')?.dataset.explicitGroup==='1').flatMap(g=>g.studentIds)));for(const box of document.querySelectorAll('#action-fields input[name=people]'))if(group.studentIds.includes(box.value))box.checked=e.target.checked||keep.has(box.value);}syncRosterGroups();return;}if(e.target.name==='people'){e.target.dataset.individuallySelected=e.target.checked?'1':'0';syncRosterGroups();}if(e.target.id==='k12-form-picker'){$('k12-selection-details').innerHTML=k12Detail(current(),e.target.value);return;}if(e.target.dataset.roll)run(()=>mutate('roll-call',{studentId:e.target.dataset.roll,day:Number(e.target.dataset.day),value:e.target.value}));});
document.addEventListener('click',async e=>{const tripButton=e.target.closest('[data-trip]'),tabButton=e.target.closest('[data-tab]');if(tripButton){active=tripButton.dataset.trip;signature=null;render();maybeStudentWelcome();return;}if(tabButton){tab=tabButton.dataset.tab;render();return;}const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,t=current(),p=t?.participants.find(p=>p.id===b.dataset.person),day=Number(b.dataset.day);
 if(a==='roster-clear-all'){for(const box of document.querySelectorAll('#action-fields input[name=people],#action-fields [data-student-group]')){box.checked=false;box.dataset.individuallySelected='0';box.dataset.explicitGroup='0';}syncRosterGroups();return;}
 if(a==='select-visible'||a==='clear-visible'){for(const row of document.querySelectorAll('[data-roster-search]'))if(!row.hidden){row.querySelector('input').checked=a==='select-visible';row.querySelector('input').dataset.individuallySelected=a==='select-visible'?'1':'0';}syncRosterGroups();return;}
 if(a==='welcome-step'){studentWelcome(b.dataset.step);return;}
 if(a==='welcome-finish'){$('action-dialog').close();tab='family';render();$('parent-contact')?.querySelector('input')?.focus();return;}
 if(a==='delivery-history'){tab='notifications';render();$('trip-delivery-history')?.focus();$('trip-delivery-history')?.scrollIntoView?.({block:'start',behavior:'smooth'});return;}
 if(a==='change-k12'){const section=$('k12-association');if(section){section.open=true;section.scrollIntoView?.({behavior:'smooth',block:'center'});$('k12-form-picker')?.focus({preventScroll:true});}return;}
 if(a==='k12-copy'){const row=handoffRows(t)[Number(b.dataset.index)],input=$('k12-copy-'+b.dataset.index);if(!row||!input)return;try{await navigator.clipboard.writeText(row.value);b.textContent='Copied ✓';note('Copied '+row.label+'. Paste into the matching K12 box.');}catch{input.focus();input.select();note('Use your browser’s Copy command, then paste into K12.');}return;}
 if(a==='download-roster'){window.open('/api/field-trips?operation=open-form&id='+encodeURIComponent(t.id)+'&requestId='+encodeURIComponent(b.dataset.request),'_blank','noopener,noreferrer');return;}
 if(a==='remove-edit-day'){const box=$('edit-days');if(box.children.length>1)box.lastElementChild.remove();else note('Keep at least one trip day. Remove all invited students to cancel its calendar events.');return;}
 if(a==='add-edit-day'){const box=$('edit-days'),n=box.children.length;if(n<5)box.insertAdjacentHTML('beforeend',dayInputs({},n));return;}
 if(a==='prepare-preview'){dialog('Prepare permission preview',`<p>The district permission template has not been generated for the current details of <strong>${esc(t.title)}</strong>. Prepare it using the original district builder, then open the form and itinerary preview.</p><p>Parents whose signatures need renewal will receive an update after the refreshed form is ready.</p>`,async()=>{let popup=null;try{popup=window.open('about:blank','_blank');if(popup){popup.opener=null;popup.document.title='Preparing TripHub preview';popup.document.body.textContent='Preparing the district permission template and itinerary…';}}catch{}try{await mutate('refresh-template');const fresh=current(),student=fresh?.participants[0];if(fresh?.id!==t.id||!fresh?.templateReady||!student)throw Error('The preview is not ready. Refresh the event and try again.');const url='/api/field-trips?operation=preview-pdf&id='+encodeURIComponent(fresh.id)+'&studentId='+encodeURIComponent(student.id);if(popup)popup.location.replace(url);else note('The form is ready. Click Preview generated form & itinerary to open it.');}catch(error){try{popup?.close();}catch{}throw error;}},'Prepare & preview');return;}
 if(a==='edit'){dialog('Edit trip details',tripFields(t),async f=>{await mutate('save-details',{trip:tripValues(f)});});return;}
 if(a==='roster-groups'){const groups=[...(data.studentGroups?.divisions||[]),...(data.studentGroups?.leadership||[]),...(data.studentGroups?.robotics||[])].filter(g=>/^(division:CTSO|leadership:CTSO|robotics:[a-z0-9:-]+)$/.test(g.id));dialog('Automatic Robotics invitations',`<p>Newly active members of these groups are added and invited automatically before departure. Existing permission records and deliberate removals are preserved.</p>${groups.map(g=>`<label class="contact"><input type="checkbox" name="automaticGroups" value="${esc(g.id)}" ${t.autoRoster?.groupIds?.includes(g.id)?'checked':''}><span>${esc(g.label)}</span></label>`).join('')}`,async f=>mutate('roster-groups',{groupIds:f.getAll('automaticGroups'),autoRoster:f.getAll('automaticGroups').length>0}),'Save groups & invite new members');return;}
 if(a==='sync-roster'){await mutate('roster-sync',{});return;}
 if(a==='roster'){dialog('Manage event students','<p>Removed students lose access immediately. Trip and deadline invitations will be reconciled; failures remain pending for retry.</p>'+rosterFields(t.participants.map(p=>p.id),t.autoRoster?.groupIds||[])+`<label class="contact"><input type="checkbox" name="autoRoster" ${t.autoRoster?.enabled!==false?'checked':''}><span>Automatically add and invite newly eligible members of the saved Robotics groups</span></label>`,async f=>mutate('participants',{participantIds:f.getAll('people'),groupIds:chosenGroupIds(),autoRoster:f.has('autoRoster')}),'Save roster & update invitations');return;}
 if(a==='calendar-plan'){await run(async()=>{const plan=await api('calendar-plan',{id:t.id},true);dialog('Review calendar invitations','<p>Freshly read from Google Calendar. Close this review to edit trip details or invited students, then refresh the review before applying.</p>'+planHtml(plan.plan),async()=>{if(current()?.id!==t.id||current()?.revision!==plan.revision)throw Error('The trip changed. Close and refresh this calendar review.');await mutate('calendar-sync');}, 'Apply calendar changes');});return;}
 if(a==='invite-parent'){dialog('Verify guardian contact',`<p>${esc(p.name)} → ${esc(p.parent.name)} · ${esc(p.parent.email)}</p><label class="contact"><input type="checkbox" name="guardianConfirmed" required><span>I checked this address against a guardian record or confirmed it directly.</span></label><p>The parent receives a private link and must verify email access before signing.</p>`,async f=>mutate('invite-parent',{studentId:p.id,guardianConfirmed:f.has('guardianConfirmed')}),'Send parent & student invitations');return;}
 if(a==='link-k12'){const form=(data.inbox||[]).find(f=>f.requestId===b.dataset.request);if(!form)return;dialog('Confirm district form association',`<p>Link form ${esc(b.dataset.request)} to <strong>${esc(t.title)}</strong>?</p><p><strong>${esc(form.details?.title||'Activity unavailable')}</strong><br>${esc(form.details?.destination||'Destination unavailable')}<br>${esc(form.details?.departDate||'Dates missing')}${form.details?.returnDate?' – '+esc(form.details.returnDate):''}</p><p>Confirm the form covers this trip. Its unique form ID will be saved and the association logged.</p>`,async()=>mutate('link-k12',{requestId:b.dataset.request}),'Confirm association');return;}
 if(a==='inspect-k12'){dialog('Inspect your district form link',field('url','Private K12 form URL','','url','required')+'<p>Kept in the organizer-only district record.</p>',async f=>{await api('inspect-k12',{url:f.get('url')});await load();},'Read form details');return;}
 if(a==='van-notify'){const office=data.contacts.filter(c=>c.office);dialog('Send van-key confirmation request',`<p>To: ${esc(office.map(c=>c.email).join(', '))}</p><p>For ${esc(t.title)}, ask the front office to verify current driver authorization, van reservation, and who/where/when for key pickup.</p><p>This request does not mark the van ready.</p>`,async()=>mutate('notify',{kind:'van'}),'Send office email');return;}
 if(a==='draw-signature'){const form=$('parent-signature');const values=Object.fromEntries(new FormData(form));signature=await window.NestSignaturePad.capture(signature||{});if(signature){const line=form.querySelector('[data-action=draw-signature]');line.replaceChildren();const image=document.createElement('img');image.src=signature.png;image.alt='Your drawn signature';line.append(image,document.createTextNode('Tap to review your signature'));}return;}
 if(['decline','verify','correction','paper-received','open-day','close-day','approve-out','van-revoke','refresh-template'].includes(a)){dialog('Confirm '+({verify:'permission verification',correction:'correction request','paper-received':'signed paper received',decline:'declined permission','open-day':'opening check-in','close-day':'closing this day','approve-out':'student departure','van-revoke':'changed van authorization','refresh-template':'district template refresh'})[a],`<p>${p?esc(p.name)+' · ':''}${esc(t.title)}</p>${a==='refresh-template'?'<p>Parents whose signatures need renewal will receive an update after the refreshed form is ready.</p>':''}`,async()=>mutate(a,{studentId:p?.id,day}),a==='refresh-template'?'Refresh template':'Confirm');return;}
 if(['check-in','request-out','sync-mail'].includes(a))await run(()=>mutate(a,{day}));
});
$('panel').addEventListener('submit',e=>{e.preventDefault();const form=e.target,f=new FormData(form),v=Object.fromEntries(f),t=current();if(form.dataset.message){run(()=>mutate('message',{studentId:form.dataset.message,message:v.message}));return;}
 if(form.id==='parent-contact'){if(v.email!==v.emailConfirm){note('The parent email entries must match.');return;}run(()=>mutate('parent-contact',{name:v.name,email:v.email}));}
 if(form.id==='parent-signature'){if(!signature){note('Draw your signature first.');return;}run(async()=>{await mutate('sign-permission',{answers:{...Object.fromEntries([...f].filter(([k])=>k!=='consent')),signaturePng:signature.png},consent:f.has('consent')});signature=null;});}
 if(form.id==='district-manual')run(()=>mutate('district-manual',v));
 if(form.id==='van-confirm')run(()=>mutate('van-confirm',{...v,driver:f.has('driver'),reserved:f.has('reserved'),keys:f.has('keys')}));
 if(form.id==='student-invitations'){const ids=f.getAll('students'),people=t.participants.filter(p=>ids.includes(p.id));if(!people.length){note('Choose at least one student.');return;}const reviewed=studentInviteSnapshot(t,ids);dialog('Review student invitations',`<p>${esc(t.title)} · ${people.length} student invitation(s), delivered individually.</p><ul>${people.map(p=>`<li>${esc(p.name)} · ${esc(p.email)}</li>`).join('')}</ul><p>Includes the trip details, permission deadline, a link to NEST™ TripHub, and steps to open My paperwork and submit a parent or guardian email for a private digital signature invitation.</p><p>Trip link: https://gknest.org/triphub#trip=${esc(t.id)}</p>`,async()=>{await load();const latest=current();if(latest?.id!==t.id||studentInviteSnapshot(latest,ids)!==reviewed)throw Error('Trip details or selected recipients changed. Close this window and review the student invitations again.');await mutate('notify',{kind:'student-invite',participantIds:ids});},'Send student invitations');}
 if(form.id==='notification'){const kind=v.kind,contacts=f.getAll('contacts'),recipients=kind==='missing'?t.participants.filter(p=>['missing','changes'].includes(p.status)).flatMap(p=>[p.email,...(p.parent&&p.parent.stage!=='contact-review'?[p.parent.email]:[])]):(data.contacts||[]).filter(c=>contacts.includes(c.id)).map(c=>c.email);dialog('Review notification',`<p><strong>${esc(kind)}</strong> · ${esc(t.title)}</p><p>To: ${esc(recipients.join(', ')||'No recipients')}</p><p>${esc(v.note||'')}</p>${['details','change'].includes(kind)?`<h3>Invited students (${t.participants.length})</h3><ul>${t.participants.map(p=>`<li>${esc(p.name)}</li>`).join('')}</ul>`:''}${f.has('calendar')&&kind!=='missing'?'<p>Also reconcile this trip’s calendar invitations.</p>':''}`,async()=>{if(f.has('calendar')&&kind!=='missing')await mutate('calendar-sync');await mutate('notify',{kind,contacts,note:v.note});},'Send notification');}
});
async function parentEntry(invite){$('workspace').hidden=true;$('new-trip').hidden=true;dialog('Parent email verification','<p>Request a verification code at the organizer-checked parent address.</p>',async()=>{const start=await api('parent-start',{inviteToken:invite});challenge=start.challenge;setTimeout(()=>dialog('Enter parent verification code',`<p>Sent to ${esc(start.maskedEmail)}.</p>`+field('code','Six-digit code','','text','required inputmode="numeric" pattern="[0-9]{6}" maxlength="6"'),async f=>{await api('parent-verify',{challenge,code:f.get('code')});await load();tab='family';render();},'Verify & open permission form'),0);},'Email verification code');}
(async()=>{const invite=new URLSearchParams(location.hash.slice(1)).get('invite');if(invite){history.replaceState(null,'',location.pathname);await parentEntry(invite);return;}await window.NestAuth.ready;try{await load();}catch{}})();
})();
